// 0-1 BFS on a grid (LeetCode 2290). JS has no deque; Array.unshift is O(n),
// so use a fixed-size ring buffer.
class Deque {
  constructor(cap) { this.buf = new Array(cap); this.head = 0; this.size = 0; this.cap = cap; }
  pushFront(x) { this.head = (this.head - 1 + this.cap) % this.cap; this.buf[this.head] = x; this.size++; }
  pushBack(x) { this.buf[(this.head + this.size) % this.cap] = x; this.size++; }
  popFront() { const x = this.buf[this.head]; this.head = (this.head + 1) % this.cap; this.size--; return x; }
}

function minimumObstacles(grid) {
  const R = grid.length, C = grid[0].length;
  const dist = Array.from({ length: R }, () => new Array(C).fill(Infinity));
  dist[0][0] = 0;
  const dq = new Deque(R * C * 2 + 1);   // a cell is pushed at most twice (d+1, then d)
  dq.pushBack([0, 0]);
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  while (dq.size) {
    const [r, c] = dq.popFront();
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nc < 0 || nr >= R || nc >= C) continue;
      const w = grid[nr][nc];
      if (dist[r][c] + w < dist[nr][nc]) {
        dist[nr][nc] = dist[r][c] + w;
        w === 0 ? dq.pushFront([nr, nc]) : dq.pushBack([nr, nc]);
      }
    }
  }
  return dist[R - 1][C - 1];
}

// Floyd-Warshall: dist is an n x n matrix, Infinity where no edge.
function floydWarshall(dist) {
  const n = dist.length;
  for (let k = 0; k < n; k++)            // k outermost
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
  return dist;
}

from collections import deque

# LeetCode 2290 Minimum Obstacle Removal to Reach Corner (0-1 BFS). O(R * C).
def minimum_obstacles(grid):
    rows, cols = len(grid), len(grid[0])
    INF = float("inf")
    dist = [[INF] * cols for _ in range(rows)]
    dist[0][0] = 0
    dq = deque([(0, 0)])
    while dq:
        r, c = dq.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                w = grid[nr][nc]                 # 0 = free, 1 = obstacle
                if dist[r][c] + w < dist[nr][nc]:
                    dist[nr][nc] = dist[r][c] + w
                    if w == 0:
                        dq.appendleft((nr, nc))  # same layer
                    else:
                        dq.append((nr, nc))      # next layer
    return dist[rows - 1][cols - 1]

# Floyd-Warshall. O(V^3) time, O(V^2) space.
def floyd_warshall(n, edges):
    INF = float("inf")
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)
    for k in range(n):                           # k MUST be outermost
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(n):
                if dik + dk[j] < di[j]:
                    di[j] = dik + dk[j]
    has_negative_cycle = any(dist[i][i] < 0 for i in range(n))
    return dist, has_negative_cycle

// LeetCode 1334: Floyd-Warshall, then count neighbours within the threshold.
static int findTheCity(int n, int[][] edges, int threshold) {
    final int INF = 1_000_000_000;
    int[][] d = new int[n][n];
    for (int[] row : d) Arrays.fill(row, INF);
    for (int i = 0; i < n; i++) d[i][i] = 0;
    for (int[] e : edges) {
        d[e[0]][e[1]] = Math.min(d[e[0]][e[1]], e[2]);
        d[e[1]][e[0]] = Math.min(d[e[1]][e[0]], e[2]);
    }
    for (int k = 0; k < n; k++)
        for (int i = 0; i < n; i++) {
            if (d[i][k] == INF) continue;       // avoids INF + INF overflow
            for (int j = 0; j < n; j++)
                if (d[k][j] != INF && d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];
        }
    int best = -1, fewest = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        int count = 0;
        for (int j = 0; j < n; j++) if (i != j && d[i][j] <= threshold) count++;
        if (count <= fewest) { fewest = count; best = i; }   // ties -> larger index
    }
    return best;
}

class DSU {
  constructor(n) { this.p = Array.from({ length: n }, (_, i) => i); this.r = new Array(n).fill(0); }
  find(x) { while (this.p[x] !== x) { this.p[x] = this.p[this.p[x]]; x = this.p[x]; } return x; }
  union(a, b) {
    a = this.find(a); b = this.find(b);
    if (a === b) return false;
    if (this.r[a] < this.r[b]) [a, b] = [b, a];
    this.p[b] = a;
    if (this.r[a] === this.r[b]) this.r[a]++;
    return true;
  }
}

// Kruskal: edges = [[w, u, v], ...]. Returns total weight, or -1 if disconnected.
function kruskal(n, edges) {
  edges.sort((x, y) => x[0] - y[0]);
  const dsu = new DSU(n);
  let total = 0, used = 0;
  for (const [w, u, v] of edges) {
    if (dsu.union(u, v)) {
      total += w;
      if (++used === n - 1) break;
    }
  }
  return used === n - 1 ? total : -1;
}

// LeetCode 1584 Min Cost to Connect All Points (Kruskal on the complete graph)
function minCostConnectPoints(points) {
  const n = points.length, edges = [];
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      edges.push([Math.abs(points[i][0] - points[j][0]) + Math.abs(points[i][1] - points[j][1]), i, j]);
  return n === 1 ? 0 : kruskal(n, edges);
}

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]  # path halving
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = self.find(a), self.find(b)
        if a == b:
            return False
        if self.rank[a] < self.rank[b]:
            a, b = b, a
        self.parent[b] = a
        if self.rank[a] == self.rank[b]:
            self.rank[a] += 1
        return True

def kruskal(n, edges):
    """edges = [(w, u, v)]. O(E log E). Returns (total, mst_edges) or None if disconnected."""
    dsu = DSU(n)
    total, chosen = 0, []
    for w, u, v in sorted(edges):
        if dsu.union(u, v):
            total += w
            chosen.append((u, v, w))
            if len(chosen) == n - 1:
                break
    return (total, chosen) if len(chosen) == n - 1 else None

static int[] parent, rank;
static int find(int x) {
    while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
}
static boolean union(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return false;
    if (rank[a] < rank[b]) { int t = a; a = b; b = t; }
    parent[b] = a;
    if (rank[a] == rank[b]) rank[a]++;
    return true;
}

// edges[i] = {u, v, w}. Returns MST weight or -1 if the graph is disconnected.
static long kruskal(int n, int[][] edges) {
    parent = new int[n]; rank = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    Arrays.sort(edges, (x, y) -> Integer.compare(x[2], y[2]));
    long total = 0; int used = 0;
    for (int[] e : edges) {
        if (union(e[0], e[1])) {
            total += e[2];
            if (++used == n - 1) break;
        }
    }
    return used == n - 1 ? total : -1;
}

struct DSU {
    vector<int> p, r;
    DSU(int n) : p(n), r(n, 0) { iota(p.begin(), p.end(), 0); }
    int find(int x) { while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; } return x; }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
        return true;
    }
};

// edges: {w, u, v}. Returns MST weight or -1 if disconnected.
long long kruskal(int n, vector<array<int,3>> edges) {
    sort(edges.begin(), edges.end());
    DSU dsu(n);
    long long total = 0; int used = 0;
    for (auto [w, u, v] : edges)
        if (dsu.unite(u, v)) { total += w; if (++used == n - 1) break; }
    return used == n - 1 ? total : -1;
}

// Array-based Prim for a complete graph: O(n^2) time, O(n) space, no edge list.
// LeetCode 1584 Min Cost to Connect All Points.
function minCostConnectPoints(points) {
  const n = points.length;
  const inTree = new Array(n).fill(false);
  const minEdge = new Array(n).fill(Infinity);
  minEdge[0] = 0;
  let total = 0;
  for (let round = 0; round < n; round++) {
    let u = -1;
    for (let v = 0; v < n; v++)                       // cheapest node outside the tree
      if (!inTree[v] && (u === -1 || minEdge[v] < minEdge[u])) u = v;
    inTree[u] = true;
    total += minEdge[u];
    for (let v = 0; v < n; v++) {                     // update keys using u
      if (inTree[v]) continue;
      const d = Math.abs(points[u][0] - points[v][0]) + Math.abs(points[u][1] - points[v][1]);
      if (d < minEdge[v]) minEdge[v] = d;
    }
  }
  return total;
}

// Lazy heap Prim. adj.get(u) = list of {v, w}. O(E log V).
static long prim(int n, List<List<int[]>> adj) {
    boolean[] inTree = new boolean[n];
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
    pq.add(new int[]{0, 0});
    long total = 0; int taken = 0;
    while (!pq.isEmpty() && taken < n) {
        int[] top = pq.poll();
        int w = top[0], u = top[1];
        if (inTree[u]) continue;
        inTree[u] = true; total += w; taken++;
        for (int[] e : adj.get(u))
            if (!inTree[e[0]]) pq.add(new int[]{e[1], e[0]});
    }
    return taken == n ? total : -1;
}

// Array-based Prim on the complete Manhattan graph: O(n^2).
int minCostConnectPoints(vector<vector<int>>& pts) {
    int n = pts.size();
    vector<int> minEdge(n, INT_MAX);
    vector<bool> inTree(n, false);
    minEdge[0] = 0;
    int total = 0;
    for (int round = 0; round < n; round++) {
        int u = -1;
        for (int v = 0; v < n; v++)
            if (!inTree[v] && (u == -1 || minEdge[v] < minEdge[u])) u = v;
        inTree[u] = true;
        total += minEdge[u];
        for (int v = 0; v < n; v++) {
            if (inTree[v]) continue;
            int d = abs(pts[u][0] - pts[v][0]) + abs(pts[u][1] - pts[v][1]);
            minEdge[v] = min(minEdge[v], d);
        }
    }
    return total;
}

// Kahn's algorithm. LeetCode 210 Course Schedule II.
// prerequisites[i] = [a, b] means b must come before a: edge b -> a.
function findOrder(numCourses, prerequisites) {
  const adj = Array.from({ length: numCourses }, () => []);
  const indegree = new Array(numCourses).fill(0);
  for (const [a, b] of prerequisites) {
    adj[b].push(a);
    indegree[a]++;
  }
  const queue = [];
  for (let i = 0; i < numCourses; i++) if (indegree[i] === 0) queue.push(i);
  const order = [];
  for (let head = 0; head < queue.length; head++) {   // array as a queue, O(1) pop
    const u = queue[head];
    order.push(u);
    for (const v of adj[u]) if (--indegree[v] === 0) queue.push(v);
  }
  return order.length === numCourses ? order : [];    // [] means a cycle exists
}

// LeetCode 207 Course Schedule: can all courses be finished?
const canFinish = (n, prereqs) => findOrder(n, prereqs).length === n;

from collections import deque

def find_order(num_courses, prerequisites):
    """Kahn's algorithm, O(V + E). Returns [] if there is a cycle."""
    adj = [[] for _ in range(num_courses)]
    indegree = [0] * num_courses
    for a, b in prerequisites:          # b before a
        adj[b].append(a)
        indegree[a] += 1
    q = deque(i for i in range(num_courses) if indegree[i] == 0)
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)
    return order if len(order) == num_courses else []

def minimum_time(n, relations, time):
    """LeetCode 2050 Parallel Courses III: longest path in a DAG (critical path)."""
    adj = [[] for _ in range(n + 1)]
    indegree = [0] * (n + 1)
    for prev, nxt in relations:
        adj[prev].append(nxt)
        indegree[nxt] += 1
    finish = [0] * (n + 1)
    q = deque()
    for i in range(1, n + 1):
        if indegree[i] == 0:
            finish[i] = time[i - 1]
            q.append(i)
    while q:
        u = q.popleft()
        for v in adj[u]:
            finish[v] = max(finish[v], finish[u] + time[v - 1])
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)
    return max(finish)

// Kahn's algorithm, O(V + E). Returns an empty array when a cycle exists.
static int[] findOrder(int n, int[][] prerequisites) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    int[] indegree = new int[n];
    for (int[] p : prerequisites) { adj.get(p[1]).add(p[0]); indegree[p[0]]++; }
    ArrayDeque<Integer> q = new ArrayDeque<>();
    for (int i = 0; i < n; i++) if (indegree[i] == 0) q.add(i);
    int[] order = new int[n];
    int k = 0;
    while (!q.isEmpty()) {
        int u = q.poll();
        order[k++] = u;
        for (int v : adj.get(u)) if (--indegree[v] == 0) q.add(v);
    }
    return k == n ? order : new int[0];
}

// Kahn's algorithm, O(V + E).
vector<int> findOrder(int n, vector<vector<int>>& prerequisites) {
    vector<vector<int>> adj(n);
    vector<int> indegree(n, 0), order;
    for (auto& p : prerequisites) { adj[p[1]].push_back(p[0]); indegree[p[0]]++; }
    queue<int> q;
    for (int i = 0; i < n; i++) if (indegree[i] == 0) q.push(i);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u);
        for (int v : adj[u]) if (--indegree[v] == 0) q.push(v);
    }
    if ((int)order.size() != n) order.clear();   // cycle
    return order;
}

// DFS topological sort with 3 colours. Returns null if there is a cycle.
// adj[u] = list of v for edges u -> v.
function topoSortDfs(n, adj) {
  const WHITE = 0, GRAY = 1, BLACK = 2;
  const color = new Array(n).fill(WHITE);
  const post = [];
  let hasCycle = false;

  function dfs(u) {
    color[u] = GRAY;
    for (const v of adj[u]) {
      if (color[v] === GRAY) { hasCycle = true; return; }   // back edge
      if (color[v] === WHITE) { dfs(v); if (hasCycle) return; }
    }
    color[u] = BLACK;
    post.push(u);
  }

  for (let i = 0; i < n && !hasCycle; i++) if (color[i] === WHITE) dfs(i);
  return hasCycle ? null : post.reverse();
}

// LeetCode 802 Find Eventual Safe States: safe = never reaches a cycle.
function eventualSafeNodes(graph) {
  const n = graph.length, color = new Array(n).fill(0);   // 0 white, 1 gray, 2 safe
  const safe = (u) => {
    if (color[u]) return color[u] === 2;
    color[u] = 1;
    for (const v of graph[u]) if (!safe(v)) return false; // stays gray = unsafe
    color[u] = 2;
    return true;
  };
  const res = [];
  for (let i = 0; i < n; i++) if (safe(i)) res.push(i);
  return res;
}

// LeetCode 207 Course Schedule with DFS colours. O(V + E).
static boolean canFinish(int n, int[][] prerequisites) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    for (int[] p : prerequisites) adj.get(p[1]).add(p[0]);
    int[] color = new int[n];                 // 0 white, 1 gray, 2 black
    for (int i = 0; i < n; i++)
        if (color[i] == 0 && hasCycle(i, adj, color)) return false;
    return true;
}
static boolean hasCycle(int u, List<List<Integer>> adj, int[] color) {
    color[u] = 1;
    for (int v : adj.get(u)) {
        if (color[v] == 1) return true;       // back edge
        if (color[v] == 0 && hasCycle(v, adj, color)) return true;
    }
    color[u] = 2;
    return false;
}

// Union-Find with path halving + union by size. ~O(α(n)) amortised per op.
class DSU {
  constructor(n) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.size = new Array(n).fill(1);
    this.components = n;
  }
  find(x) {
    while (this.parent[x] !== x) {
      this.parent[x] = this.parent[this.parent[x]];  // path halving
      x = this.parent[x];
    }
    return x;
  }
  union(a, b) {
    let ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false;                     // already connected
    if (this.size[ra] < this.size[rb]) [ra, rb] = [rb, ra];
    this.parent[rb] = ra;                            // small under large
    this.size[ra] += this.size[rb];
    this.components--;
    return true;
  }
  connected(a, b) { return this.find(a) === this.find(b); }
}

// LeetCode 684 Redundant Connection (nodes 1..n)
function findRedundantConnection(edges) {
  const dsu = new DSU(edges.length + 1);
  for (const [u, v] of edges) if (!dsu.union(u, v)) return [u, v];
  return [];
}

// LeetCode 547 Number of Provinces (adjacency matrix)
function findCircleNum(isConnected) {
  const n = isConnected.length, dsu = new DSU(n);
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) if (isConnected[i][j]) dsu.union(i, j);
  return dsu.components;
}

class DSU:
    """Path halving + union by rank. Amortised O(alpha(n)) per operation."""

    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.components = n

    def find(self, x):
        parent = self.parent
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        self.components -= 1
        return True

def make_connected(n, connections):
    """LeetCode 1319: minimum cables to move so the network is connected."""
    if len(connections) < n - 1:
        return -1
    dsu = DSU(n)
    for a, b in connections:
        dsu.union(a, b)
    return dsu.components - 1

class DSU {
    private final int[] parent, size;
    int components;

    DSU(int n) {
        parent = new int[n]; size = new int[n]; components = n;
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
    }

    int find(int x) {                       // full path compression, recursive
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
        components--;
        return true;
    }

    int sizeOf(int x) { return size[find(x)]; }
}

struct DSU {
    vector<int> parent, sz;
    int components;
    explicit DSU(int n) : parent(n), sz(n, 1), components(n) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
        components--;
        return true;
    }
};

// LeetCode 721 Accounts Merge with a small inline DSU.
function accountsMerge(accounts) {
  const parent = accounts.map((_, i) => i);
  const find = (x) => {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  };
  const owner = new Map();                      // email -> account index
  accounts.forEach(([, ...emails], i) => {
    for (const e of emails) {
      if (owner.has(e)) parent[find(i)] = find(owner.get(e));
      else owner.set(e, i);
    }
  });
  const groups = new Map();                     // root -> emails
  for (const [e, i] of owner) {
    const r = find(i);
    if (!groups.has(r)) groups.set(r, []);
    groups.get(r).push(e);
  }
  return [...groups].map(([r, es]) => [accounts[r][0], ...es.sort()]);
}

from collections import defaultdict

def accounts_merge(accounts):
    """LeetCode 721. Union accounts that share an email."""
    parent = list(range(len(accounts)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    owner = {}                                  # email -> first account index
    for i, (_, *emails) in enumerate(accounts):
        for e in emails:
            if e in owner:
                parent[find(i)] = find(owner[e])
            else:
                owner[e] = i

    groups = defaultdict(list)
    for e, i in owner.items():
        groups[find(i)].append(e)
    return [[accounts[r][0]] + sorted(es) for r, es in groups.items()]

def remove_stones(stones):
    """LeetCode 947. Rows and columns are nodes; each stone is an edge."""
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for r, c in stones:
        parent[find(r)] = find(~c)              # ~c keeps columns apart from rows
    roots = {find(x) for x in parent}
    return len(stones) - len(roots)

def equations_possible(equations):
    """LeetCode 990. Union all '==' first, then check every '!='."""
    parent = list(range(26))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for e in equations:
        if e[1] == "=":
            parent[find(ord(e[0]) - 97)] = find(ord(e[3]) - 97)
    return all(find(ord(e[0]) - 97) != find(ord(e[3]) - 97)
               for e in equations if e[1] == "!")

// LeetCode 827 Making A Large Island: DSU by size over grid cells.
static int[] parent, size;
static int find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
static void union(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return;
    if (size[a] < size[b]) { int t = a; a = b; b = t; }
    parent[b] = a; size[a] += size[b];
}

static int largestIsland(int[][] grid) {
    int n = grid.length;
    parent = new int[n * n]; size = new int[n * n];
    for (int i = 0; i < n * n; i++) { parent[i] = i; size[i] = 1; }
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++) {
            if (grid[r][c] == 0) continue;
            if (r + 1 < n && grid[r + 1][c] == 1) union(r * n + c, (r + 1) * n + c);
            if (c + 1 < n && grid[r][c + 1] == 1) union(r * n + c, r * n + c + 1);
        }
    int best = 0;
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++) {
            if (grid[r][c] == 1) { best = Math.max(best, size[find(r * n + c)]); continue; }
            Set<Integer> roots = new HashSet<>();
            int total = 1;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr < 0 || nc < 0 || nr >= n || nc >= n || grid[nr][nc] == 0) continue;
                int root = find(nr * n + nc);
                if (roots.add(root)) total += size[root];   // count each island once
            }
            best = Math.max(best, total);
        }
    return best;
}
